"""foreach_mul_ (Tensor overload) implemented with Triton kernels.

For every tensor T in the Python sequence ``self``: T <- T * other, written
in place.  ``other`` is a single-element device tensor (a matching shaped
tensor is also supported through a broadcast-aware strided kernel).

All members of the sequence that share a dtype, are contiguous and do not
alias each other are fused into a single multi-slot kernel launch; the
launch cost is the dominant non-bandwidth cost on the target.
"""

import torch
import triton
import triton.language as tl

_MAX_DIMS = 4
_FUSE = 4
# Pipeline stages for the fused kernel.  The multi-buffer pass materialises
# `num_stages` copies of the tile buffers in the unified buffer, so this is the
# knob that decides how wide a tile can compile at all.
_NUM_STAGES = 1

# Reusing a compiled kernel's launcher skips the JIT dispatch layer.  It is
# used only for an exactly reproduced specialization, and any failure disables
# it for the rest of the process so the standard launch path takes over.
_LAUNCH_CACHE = {}
_FAST_OK = False
_knobs = None
_driver = None
try:
    from triton import knobs as _knobs
    from triton.runtime import driver as _driver

    _FAST_OK = True
except Exception:  # pragma: no cover - keep the standard launch path
    _knobs = None
    _driver = None


def _disable_fast_launch():
    global _FAST_OK
    _FAST_OK = False
    _LAUNCH_CACHE.clear()


def _relaunch(kernel, grid0, args):
    """Launch an already compiled kernel without re-entering JIT dispatch."""
    drv = _driver.active
    stream = drv.get_current_stream(drv.get_current_device())
    meta_fn = getattr(kernel, "launch_metadata", None)
    meta = meta_fn((grid0, 1, 1), stream, *args) if meta_fn is not None else None
    kernel.foreach_mul_tensor_(
        grid0,
        1,
        1,
        stream,
        kernel.function,
        kernel.packed_metadata,
        meta,
        _knobs.runtime.launch_enter_hook,
        _knobs.runtime.launch_exit_hook,
        *args,
    )


