@triton.jit
def _mul_tile(x_ptr, b_ptr, lp, n, BLOCK: tl.constexpr, MODE: tl.constexpr):
    """Multiply one aligned tile of ``x`` by the scalar loaded from ``b``."""
    offs = lp * BLOCK + tl.arange(0, BLOCK)
    b = tl.load(b_ptr)
    if lp < n // BLOCK:
        a = tl.load(x_ptr + offs)
        if MODE == 0:
            r = (a.to(tl.float32) * b.to(tl.float32)).to(x_ptr.dtype.element_ty)
        elif MODE == 1:
            r = (a.to(tl.float64) * b.to(tl.float64)).to(x_ptr.dtype.element_ty)
        elif MODE == 3:
            r = a * b.to(x_ptr.dtype.element_ty)
        else:
            r = (a.to(tl.int64) * b.to(tl.int64)).to(x_ptr.dtype.element_ty)
        tl.store(x_ptr + offs, r)
    else:
        m = offs < n
        a = tl.load(x_ptr + offs, mask=m)
        if MODE == 0:
            r = (a.to(tl.float32) * b.to(tl.float32)).to(x_ptr.dtype.element_ty)
        elif MODE == 1:
            r = (a.to(tl.float64) * b.to(tl.float64)).to(x_ptr.dtype.element_ty)
        elif MODE == 3:
            r = a * b.to(x_ptr.dtype.element_ty)
        else:
            r = (a.to(tl.int64) * b.to(tl.int64)).to(x_ptr.dtype.element_ty)
        tl.store(x_ptr + offs, r, mask=m)


@triton.jit
def _mul_fused_kernel(
    x0,
    x1,
    x2,
    x3,
    b_ptr,
    n0,
    n1,
    n2,
    n3,
    BLOCK: tl.constexpr,
    MODE: tl.constexpr,
    NSLOT: tl.constexpr,
):
    pid = tl.program_id(0)
    if NSLOT == 1:
        _mul_tile(x0, b_ptr, pid, n0, BLOCK, MODE)
    elif NSLOT == 2:
        c1 = (n0 + BLOCK - 1) // BLOCK
        if pid < c1:
            _mul_tile(x0, b_ptr, pid, n0, BLOCK, MODE)
        else:
            _mul_tile(x1, b_ptr, pid - c1, n1, BLOCK, MODE)
    elif NSLOT == 3:
        c1 = (n0 + BLOCK - 1) // BLOCK
        c2 = c1 + (n1 + BLOCK - 1) // BLOCK
        if pid < c1:
            _mul_tile(x0, b_ptr, pid, n0, BLOCK, MODE)
        elif pid < c2:
            _mul_tile(x1, b_ptr, pid - c1, n1, BLOCK, MODE)
        else:
            _mul_tile(x2, b_ptr, pid - c2, n2, BLOCK, MODE)
    else:
        c1 = (n0 + BLOCK - 1) // BLOCK
        c2 = c1 + (n1 + BLOCK - 1) // BLOCK
        c3 = c2 + (n2 + BLOCK - 1) // BLOCK
        if pid < c1:
            _mul_tile(x0, b_ptr, pid, n0, BLOCK, MODE)
        elif pid < c2:
            _mul_tile(x1, b_ptr, pid - c1, n1, BLOCK, MODE)
        elif pid < c3:
            _mul_tile(x2, b_ptr, pid - c2, n2, BLOCK, MODE)
        else:
            _mul_tile(x3, b_ptr, pid - c3, n3, BLOCK, MODE)


@triton.jit
def _mul_flat_kernel(
    x_ptr,
    b_ptr,
    n,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    MODE: tl.constexpr,
):
    """Elementwise multiply with a same-shaped contiguous ``other``."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        a = tl.load(x_ptr + offs)
        b = tl.load(b_ptr + offs)
        if MODE == 0:
            r = (a.to(tl.float32) * b.to(tl.float32)).to(x_ptr.dtype.element_ty)
        elif MODE == 1:
            r = (a.to(tl.float64) * b.to(tl.float64)).to(x_ptr.dtype.element_ty)
        else:
            r = (a.to(tl.int64) * b.to(tl.int64)).to(x_ptr.dtype.element_ty)
        tl.store(x_ptr + offs, r)
    else:
        m = offs < n
        a = tl.load(x_ptr + offs, mask=m)
        b = tl.load(b_ptr + offs, mask=m)
        if MODE == 0:
            r = (a.to(tl.float32) * b.to(tl.float32)).to(x_ptr.dtype.element_ty)
        elif MODE == 1:
            r = (a.to(tl.float64) * b.to(tl.float64)).to(x_ptr.dtype.element_ty)
        else:
            r = (a.to(tl.int64) * b.to(tl.int64)).to(x_ptr.dtype.element_ty)
        tl.store(x_ptr + offs, r, mask=m)


@triton.jit
def _mul_strided_kernel(
    x_ptr,
    b_ptr,
    n,
    xs0,
    xs1,
    xs2,
    xs3,
    xt0,
    xt1,
    xt2,
    xt3,
    bs0,
    bs1,
    bs2,
    bs3,
    bt0,
    bt1,
    bt2,
    bt3,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
    MODE: tl.constexpr,
    BSCALAR: tl.constexpr,
):
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n
    xo = tl.zeros([BLOCK], tl.int64)
    bo = tl.zeros([BLOCK], tl.int64)
    if RANK > 0:
        i = idx % xs0
        idx = idx // xs0
        xo += i.to(tl.int64) * xt0
        if not BSCALAR:
            bo += (i % bs0).to(tl.int64) * bt0
    if RANK > 1:
        i = idx % xs1
        idx = idx // xs1
        xo += i.to(tl.int64) * xt1
        if not BSCALAR:
            bo += (i % bs1).to(tl.int64) * bt1
    if RANK > 2:
        i = idx % xs2
        idx = idx // xs2
        xo += i.to(tl.int64) * xt2
        if not BSCALAR:
            bo += (i % bs2).to(tl.int64) * bt2
    if RANK > 3:
        i = idx % xs3
        idx = idx // xs3
        xo += i.to(tl.int64) * xt3
        if not BSCALAR:
            bo += (i % bs3).to(tl.int64) * bt3

    a = tl.load(x_ptr + xo, mask=mask)
    if BSCALAR:
        b = tl.load(b_ptr)
    else:
        b = tl.load(b_ptr + bo, mask=mask)
    if MODE == 0:
        r = (a.to(tl.float32) * b.to(tl.float32)).to(x_ptr.dtype.element_ty)
    elif MODE == 1:
        r = (a.to(tl.float64) * b.to(tl.float64)).to(x_ptr.dtype.element_ty)
    else:
        r = (a.to(tl.int64) * b.to(tl.int64)).to(x_ptr.dtype.element_ty)
    tl.store(x_ptr + xo, r, mask=mask)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _mode_of(dtype):
    if dtype in (torch.float16, torch.bfloat16, torch.float32):
        return 0
    if dtype == torch.float64:
        return 1
    return 2


def _pick_block(n, esize, opmath):
    # Each program instance pays a fixed per-tile cost (exposed DMA wait plus
    # the conversion/multiply chain), so a wider tile amortizes it over more
    # bytes.  The widest tile that keeps one input buffer, one output buffer
    # (and the fp32 opmath temporary, when used) inside a 32 KB-per-buffer
    # budget is the largest that still compiles: doubling it overflows the
    # unified buffer (measured: 384 KB required against 192 KB available).
    max_elems = 4096
    for cand in (32768, 16384, 8192, 4096):
        need = cand * esize * 2 + (cand * 4 if opmath else 0)
        if need <= 131072:
            max_elems = cand
            break
    if n >= max_elems:
        return max_elems
    b = 256
    while b < n:
        b <<= 1
    return b


def _collapse(shape, strides):
    """Merge adjacent dims that are contiguous (stride-wise) into one dim."""
    dims = []
    for s, st in zip(shape, strides):
        s = int(s)
        st = int(st)
        if s == 1:
            continue
        if dims:
            ps, pst = dims[-1]
            if st != 0 and pst != 0 and pst * ps == st:
                dims[-1] = (ps * s, pst)
                continue
        dims.append((s, st))
    return dims


def _strided_args(x, other):
    """Aligned (xshape, xstride, bshape, bstride) lists, or None if invalid."""
    collapse = other.numel() == 1
    if collapse:
        dims = _collapse(x.shape, x.stride())
        xs = [d[0] for d in dims]
        xst = [d[1] for d in dims]
    else:
        xs = [int(v) for v in x.shape]
        xst = [int(v) for v in x.stride()]
    r = len(xs)
    if r > _MAX_DIMS:
        return None
    if collapse:
        bs = [1] * r
        bt = [0] * r
    else:
        bshape = [int(v) for v in other.shape]
        bstride = [int(v) for v in other.stride()]
        q = len(bshape)
        if q > r:
            return None
        shift = r - q
        bs = []
        bt = []
        for d in range(r):
            if d < shift:
                bs.append(1)
                bt.append(0)
            else:
                sd = bshape[d - shift]
                if sd == 1:
                    bs.append(1)
                    bt.append(0)
                else:
                    if xs[d] % sd != 0:
                        return None
                    bs.append(sd)
                    bt.append(bstride[d - shift])
    return xs, xst, bs, bt


def _pad(values, fill):
    out = list(values)
    out.extend([fill] * (_MAX_DIMS - len(out)))
    return out


def _launch_fused(slots, other):
    dt = slots[0].dtype
    esize = slots[0].element_size()
    mode = _mode_of(dt)
    if mode == 0 and dt in (torch.float16, torch.bfloat16) and other.dtype == dt:
        # The product of two same-dtype floats is exact in fp32, so a native
        # dtype multiply rounds identically while dropping the fp32 temporary
        # and its two conversion passes from the per-tile chain.
        mode = 3
    k = len(slots)
    x0 = slots[0]
    n0 = x0.numel()
    x1 = slots[1] if k > 1 else x0
    n1 = x1.numel() if k > 1 else 0
    x2 = slots[2] if k > 2 else x0
    n2 = x2.numel() if k > 2 else 0
    x3 = slots[3] if k > 3 else x0
    n3 = x3.numel() if k > 3 else 0
    block = _pick_block(max(n0, n1, n2, n3), esize, mode == 0 and esize < 4)
    total = (
        (n0 + block - 1) // block
        + (n1 + block - 1) // block
        + (n2 + block - 1) // block
        + (n3 + block - 1) // block
    )
    args = (x0, x1, x2, x3, other, n0, n1, n2, n3, block, mode, k)
    if _FAST_OK:
        # Reuse the compiled kernel's own launcher once this exact
        # specialization (dtype, block, slot count, sizes, pointer alignment)
        # has been launched through the normal path at least once.
        key = (
            x0.device.index,
            dt,
            mode,
            block,
            k,
            n0,
            n1,
            n2,
            n3,
            x0.data_ptr() & 15,
            x1.data_ptr() & 15,
            x2.data_ptr() & 15,
            x3.data_ptr() & 15,
            other.data_ptr() & 15,
        )
        kernel = _LAUNCH_CACHE.get(key)
        if kernel is not None:
            try:
                _relaunch(kernel, total, args)
                return
            except Exception:
                # Never retry blindly: a failed relaunch disables the path for
                # the rest of the process and the standard launch runs below.
                _disable_fast_launch()
    kernel = _mul_fused_kernel[(total,)](
        x0,
        x1,
        x2,
        x3,
        other,
        n0,
        n1,
        n2,
        n3,
        BLOCK=block,
        MODE=mode,
        NSLOT=k,
        num_stages=_NUM_STAGES,
    )
    if _FAST_OK and kernel is not None and not hasattr(kernel, "result"):
        _LAUNCH_CACHE[key] = kernel


def _launch_strided(x, other, mode):
    n = x.numel()
    esize = x.element_size()
    block = _pick_block(n, esize, mode == 0 and esize < 4)
    grid = ((n + block - 1) // block,)
    args = _strided_args(x, other)
    if args is None:
        # Fall back to slicing the first non-unit dimension on the host.
        for d, sdim in enumerate(x.shape):
            if sdim > 1:
                for i in range(sdim):
                    _launch_strided(x.select(d, i), other, mode)
                return
        raise RuntimeError("foreach_mul_: unsupported tensor layout")
    xs, xst, bs, bt = args
    _mul_strided_kernel[grid](
        x,
        other,
        n,
        *_pad(xs, 1),
        *_pad(xst, 0),
        *_pad(bs, 1),
        *_pad(bt, 0),
        RANK=len(xs),
        BLOCK=block,
        MODE=mode,
        BSCALAR=(other.numel() == 1),
    )


def _launch_one(x, other):
    mode = _mode_of(x.dtype)
    if x.is_contiguous():
        if other.numel() == 1:
            _launch_fused([x], other)
            return
        if other.is_contiguous() and other.shape == x.shape:
            n = x.numel()
            esize = x.element_size()
            block = _pick_block(n, esize, mode == 0 and esize < 4)
            grid = ((n + block - 1) // block,)
            _mul_flat_kernel[grid](
                x, other, n, BLOCK=block, EVEN=(n % block == 0), MODE=mode
            )
            return
    _launch_strided(x, other, mode)


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def foreach_mul_tensor_(self, other):
    tensors = self if isinstance(self, (list, tuple)) else [self]
    if len(tensors) == 0:
        return None

    device = None
    for t in tensors:
        if t.numel() > 0:
            device = t.device
            break
    if device is None:
        return None

    if not torch.is_tensor(other):
        other = torch.tensor(other, device=device)
    elif other.device != device:
        other = other.to(device)

    k = len(tensors)
    if k == 1:
        t = tensors[0]
        if t.numel() != 0:
            _launch_one(t, other)
        return None

    if other.numel() == 1:
        dtype0 = tensors[0].dtype
        fused_ok = True
        for t in tensors:
            if t.dtype != dtype0 or t.numel() == 0 or not t.is_contiguous():
                fused_ok = False
                break
        if fused_ok:
            # Cheap address-interval overlap test: two distinct allocations can
            # never overlap, and members sharing a storage must stay sequential
            # because eager applies the multiply once per list entry.
            spans = []
            for t in tensors:
                start = t.data_ptr()
                spans.append((start, start + t.numel() * t.element_size()))
            for i in range(k):
                lo_i, hi_i = spans[i]
                for j in range(i + 1, k):
                    lo_j, hi_j = spans[j]
                    if lo_i < hi_j and lo_j < hi_i:
                        fused_ok = False
                        break
                if not fused_ok:
                    break
        if fused_ok:
            for i in range(0, k, _FUSE):
                _launch_fused(tensors[i : i + _FUSE], other)
            return None

    for t in tensors:
        if t.numel() == 0:
            continue
        _launch_one(t, other)
    return None
